# -*- coding: utf-8 -*-
# Таблицы в условиях (47 задач): markdown-таблицы не отображаются рендерером (KaTeX), в 35 задачах разметка
# попала внутрь $…$. Таблицы переписаны в KaTeX-array по учебнику (сканы/OCR/текстовый слой), попутно
# пересчитаны ключи. 26.09
P = {}
T = lambda s: r"\text{" + s + "}"
EMPTY = r"\phantom{00}"


def arr(rows, left=True, small=None):
    n = max(len(r) for r in rows)
    spec = "|" + ("l|" if left else "c|") + "c|" * (n - 1)
    cells = lambda r: " & ".join((T(str(c)) if str(c) in ("№", "—") else str(c) if c != "" else EMPTY) for c in list(r) + [""] * (n - len(r)))
    body = r"\begin{array}{" + spec + r"}\hline " + r" \\ \hline ".join(cells(r) for r in rows) + r" \\ \hline\end{array}"
    return "$$" + (r"{\small " + body + "}" if (n > 7 if small is None else small) else body) + "$$"


W = "таблица в условии не отображалась (разметка таблицы, не поддерживаемая рендерером, местами внутри формул) — переписана в формате KaTeX по учебнику"
S = lambda b: f"учебник ({b}) + пересчёт, 26.09"


def E(t, q, why=W, src=S("скан/OCR"), **kw):
    P[t] = dict(q=q, why=why, src=src, **kw)


